<script setup>
import { computed,onMounted,onBeforeUnmount,ref,reactive,watch } from 'vue'
import { RefreshCw,Download,ChevronDown,ShieldCheck } from 'lucide-vue-next'
import { api } from '../api'
import { can } from '../auth'
const summary=ref({}),data=ref({items:[],total:0}),busy=ref(false),error=ref(''),page=ref(1),expanded=ref(null),exporting=ref(false)
const filter=reactive({range:'today',from:'',to:'',actor:'',action:'',resource_type:'',result:'',q:''})
const labels={LOGIN:'登录',LOGOUT:'退出',PASSWORD:'修改密码',CREATE:'新增',EDIT:'修改',DELETE:'删除',START:'启动',STOP:'停止',PAUSE:'暂停',RESUME:'恢复',RETRY:'重试',RECONCILE:'发起核对',RERUN:'受理恢复',RECOVERY:'恢复结果',EXPORT:'导出',ENABLE:'启用',DISABLE:'停用','RESET-PASSWORD':'重置密码'}
function params(){const p=new URLSearchParams({page:page.value-1,size:50});for(const k of ['actor','action','resource_type','result','q'])if(filter[k])p.set(k,filter[k]);if(filter.range==='custom'){if(filter.from)p.set('from',new Date(filter.from).toISOString());if(filter.to)p.set('to',new Date(filter.to).toISOString())}else{const d=new Date();d.setHours(0,0,0,0);if(filter.range==='7d')d.setDate(d.getDate()-6);p.set('from',d.toISOString())}return p}
let requestId=0
async function load(){const id=++requestId;busy.value=true;error.value='';try{const [rows,counts]=await Promise.all([api('/audit-logs?'+params()),api('/audit-logs/summary')]);if(id===requestId){data.value=rows;summary.value=counts}}catch(e){if(id===requestId)error.value=e.message}finally{if(id===requestId)busy.value=false}}
let debounce
watch(filter,()=>{page.value=1;clearTimeout(debounce);debounce=setTimeout(load,300)})
async function download(){exporting.value=true;try{const blob=await api('/audit-logs/export?'+params(),{blob:true});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='audit-log.csv';a.click();URL.revokeObjectURL(url);await load()}catch(e){error.value=e.message}finally{exporting.value=false}}
function pretty(v){if(!v)return '无';try{return JSON.stringify(JSON.parse(v),null,2)}catch{return String(v)}}
const metrics=computed(()=>[{label:'今日操作',value:summary.value.TOTAL,color:'info'},{label:'关键操作',value:summary.value.CRITICAL,color:'warning'},{label:'异常操作',value:summary.value.FAILED,color:'danger'},{label:'活跃用户',value:summary.value.ACTORS,color:'success'}])
onMounted(load)
onBeforeUnmount(()=>{requestId++;clearTimeout(debounce)})
</script>
<template><section class="audit-page"><div class="page-controls"><span class="dim"><ShieldCheck :size="14"/> 操作留痕 · 默认保留 180 天</span><div class="header-actions"><cdc-button v-if="can()" size="small" :loading="exporting" @click="download"><Download :size="14"/>导出 CSV</cdc-button><cdc-button size="small" :loading="busy" @click="load"><RefreshCw :size="14"/>刷新</cdc-button></div></div><div class="kpi-grid"><div v-for="m in metrics" :key="m.label" class="kpi"><div class="kpi-label">{{m.label}}</div><div class="kpi-value" :class="'text-'+m.color">{{m.value??'—'}}</div></div></div><div class="toolbar audit-filters"><cdc-select v-model="filter.range"><cdc-option label="今日" value="today"/><cdc-option label="最近 7 天" value="7d"/><cdc-option label="自定义时间" value="custom"/></cdc-select><template v-if="filter.range==='custom'"><input v-model="filter.from" type="datetime-local" aria-label="开始时间"/><input v-model="filter.to" type="datetime-local" aria-label="结束时间"/></template><input v-model="filter.actor" placeholder="操作人用户名" aria-label="操作人"/><cdc-select v-model="filter.action" clearable placeholder="操作类型"><cdc-option v-for="(label,key) in labels" :key="key" :label="label" :value="key"/></cdc-select><cdc-select v-model="filter.resource_type" clearable placeholder="资源类型"><cdc-option v-for="(label,key) in {tasks:'任务',auth:'登录与账号',users:'用户',sources:'源连接',targets:'目标连接',mail:'邮件',settings:'系统'}" :key="key" :label="label" :value="key"/></cdc-select><cdc-select v-model="filter.result" clearable placeholder="全部结果"><cdc-option label="成功" value="SUCCESS"/><cdc-option label="失败" value="FAILED"/></cdc-select><input v-model="filter.q" placeholder="搜索资源或原因" aria-label="搜索审计"/></div><div v-if="error" class="alert-bar error" role="alert">{{error}}</div><div class="table-wrap" :aria-busy="busy"><table><thead><tr><th></th><th>时间</th><th>操作人</th><th>操作</th><th>资源</th><th>结果</th><th>来源 IP</th></tr></thead><tbody><template v-for="row in data.items" :key="row.ID"><tr><td><button class="icon-btn" :aria-expanded="expanded===row.ID" aria-label="展开审计详情" @click="expanded=expanded===row.ID?null:row.ID"><ChevronDown :size="14"/></button></td><td class="mono">{{new Date(row.OCCURRED_AT).toLocaleString()}}</td><td>{{row.ACTOR}}</td><td><span class="badge badge-info">{{labels[row.ACTION]||row.ACTION}}</span></td><td class="audit-resource">{{row.RESOURCE_NAME||row.RESOURCE_ID||row.RESOURCE_TYPE}}</td><td><span class="badge" :class="row.RESULT==='SUCCESS'?'badge-success':'badge-danger'">{{row.RESULT==='SUCCESS'?'成功':'失败'}}</span></td><td class="mono">{{row.IP||'系统作业'}}</td></tr><tr v-if="expanded===row.ID"><td colspan="7"><p>{{row.REASON||'—'}}</p><p class="mono dim">请求 ID：{{row.REQUEST_ID||'—'}}<span v-if="row.RECOVERY_ID"> · 恢复作业：{{row.RECOVERY_ID}}</span></p><div class="audit-expand-inner"><div class="audit-diff-box"><div class="diff-title">变更前（脱敏）</div><pre>{{pretty(row.BEFORE_JSON)}}</pre></div><div class="audit-diff-box"><div class="diff-title">变更后（脱敏）</div><pre>{{pretty(row.AFTER_JSON)}}</pre></div></div></td></tr></template><tr v-if="!data.items.length"><td colspan="7" class="empty-state">{{busy?'正在加载…':'当前筛选下没有审计日志'}}</td></tr></tbody></table></div><cdc-pagination v-model:current-page="page" :page-size="50" :total="data.total" @current-change="load"/></section></template>
